---FillSkillCardOriginData
---填充卡池原始数据(卡牌重新选择使用)(保存逻辑层的原始数据，并且给UI卡牌上的LB里面同步数据)
function UIBattlingSkillPoolPanel:FillSkillCardOriginData(data)
    self.skillPoolArrOriginDataTop = nil
    self.skillPoolArrOriginDataDown = nil
    self.skillPoolArrOriginDataTop = {}
    self.skillPoolArrOriginDataDown = {}
    for i = 1, #data.r1 do
        local roleId = Tools.splitToNum(data.r1[i], "_")[1]
        local skillIndexId = Tools.splitToNum(data.r1[i], "_")[2]
        local skillStars = Tools.splitToNum(data.r1[i], "_")[3]
        table.insert(self.skillPoolArrOriginDataTop, SkillDataVo.New(roleId, UIBattlingDataMgr:GetSkillIdByCamp(BattleInfo.myCamp, roleId, skillIndexId), skillStars, skillIndexId))
    end
    for i = 1, #data.r2 do
        local roleId = Tools.splitToNum(data.r2[i], "_")[1]
        local skillIndexId = Tools.splitToNum(data.r2[i], "_")[2]
        local skillStars = Tools.splitToNum(data.r2[i], "_")[3]
        table.insert(self.skillPoolArrOriginDataDown, SkillDataVo.New(roleId, UIBattlingDataMgr:GetSkillIdByCamp(BattleInfo.myCamp, roleId, skillIndexId), skillStars, skillIndexId))
    end
    xTry(function()
                local skillPoolSync = self:CheckSkillListSync(self:GetSkillPoolDataByClient())
                if not skillPoolSync then
                    self:RefreshSkillPool()
                end 
            end
    )
    -- print("->TestReset_UIBattlingSkillPoolPanel:FillSkillCardOriginData", 
    --         table.dump(data), table.dump(checkTable(self.skillPoolArrOriginDataTop)), table.dump(checkTable(self.skillPoolArrOriginDataDown)))
end

--- 同步逻辑原始数据和UI卡牌LB上的数据
function UIBattlingSkillPoolPanel:RefreshSkillPool()
    local _FuncSync = function(listTrans, listData)
        for i, poolPos in ipairs(listTrans) do
            local skillDataInLogic = listData[i]
            local skillPos = poolPos.position
            local skillPosLB = poolPos.luaBehaviour
            if skillDataInLogic then
                local skillCardLB
                if isNull(skillPosLB) then
                    skillCardLB = GetLuaBehaviour(UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_SKILLCARD_GO, skillPos), Constants.UIBattlingLuaTablePath.SkillCardsNodePath)
                    listTrans[i].luaBehaviour = skillCardLB
                else
                    skillCardLB = skillPosLB
                end
                -- 设置卡牌信息
                local skillCard = skillCardLB.Env
                skillCard:SetSkillCardInfo(skillDataInLogic)
                skillCard:SetSkillCardsPoolGO(self.SkillCardsPool.gameObject)
                skillCard:SetCardAimTrans(skillPos)
                skillCard:SetSkillCardPosInfo(listTrans == self.skillPoolTransArrLineTop and 1 or 2, i)
                skillCard.defaultScale = SkillCardScale
                skillCard.controller.transform.localScale = Vector3.one * SkillCardScale -- New 重设技能卡游戏物体 缩放
                skillCard:SetSkillCardCG2Show()
                skillCard:SetFatherTrans(skillPos)
                skillCard:SkillCardPosReset()
            else
                if skillPosLB then
                    local skillCard = skillPosLB.Env
                    skillCard:SetSkillCardDefault()
                    poolPos.luaBehaviour = nil
                end
            end
        end
    end
    _FuncSync(self.skillPoolTransArrLineTop, self.skillPoolArrOriginDataTop)
    _FuncSync(self.skillPoolTransArrLineDown, self.skillPoolArrOriginDataDown)
end

