--- 设置属性克制图标状态
---@param roleId integer 选中的目标
function UIBattlingSkillPoolPanel:SetSkillCardImgRestraint(roleId)
    local elementRoleAim = checkNumber(UIBattlingDataMgr:GetCharacterAttriById(roleId))
    local elementRestraint, elementBeRestraint = UIBattlingTools.GetRestraintElement(elementRoleAim)
    local _func = function(listTrans)
        local attackLable = Constants.SkillLabel.Attack
        local attackBuffLable = Constants.SkillLabel.AttackAndBuff
        local attackDebuggLable = Constants.SkillLabel.AttackAndDebuff
        for i, poolPos in ipairs(listTrans) do
            local skillCardNode = poolPos.luaBehaviour
            if skillCardNode then
                local skillCard = skillCardNode.Env
                local roleIdSC = checkNumber(skillCard.skillCardRoleId)
                local roleView = BattleViewMgr:FindRoleView(roleIdSC)
                if roleView and roleView.roleData then
                    local elementSC = checkNumber(roleView.roleData.attribute)
                    local cardType = checkNumber(skillCard.cardType)
                    if cardType == attackLable or cardType == attackBuffLable or cardType == attackDebuggLable then
                        if table.isContain(elementBeRestraint, elementSC) then
                            skillCard:SetImgRestraint(true, 2)
                        elseif table.isContain(elementRestraint, elementSC) then
                            skillCard:SetImgRestraint(true, 1)
                        else
                            skillCard:SetImgRestraint(false)
                        end
                    else
                        skillCard:SetImgRestraint(false)
                    end
                end
            end
        end
    end
    _func(self.skillPoolTransArrLineTop)
    _func(self.skillPoolTransArrLineDown)
end

--- 隐藏属性克制图标
function UIBattlingSkillPoolPanel:HideSkillCardImgRestraint()
    local _func = function(listTrans)
        for i, poolPos in ipairs(listTrans) do
            local skillCardNode = poolPos.luaBehaviour
            if skillCardNode then
                local skillCard = skillCardNode.Env
                skillCard:SetImgRestraint(false)
            end
            
        end
    end
    _func(self.skillPoolTransArrLineTop)
    _func(self.skillPoolTransArrLineDown)
end

---CheckSkillListSync
---检查技能卡池同步状态(检查逻辑原始数据和UI卡牌LB上的数据是否一致)
---@param listTop table 缓存技能池行
---@param listDown table 缓存技能池行
function UIBattlingSkillPoolPanel:CheckSkillListSync(listTop, listDown)
    local _CheckSync = function(graphList, dataList)
        for i = 1, #graphList do
            local dataInLogic = graphList[i]
            local dataInlist = dataList[i]
            if isNull(dataInLogic and dataInlist) and (not isNull(dataInLogic or dataInlist)) then
                print(table.dump({ "->卡牌不同", logic = dataInLogic, ui = dataInlist}))
                return false
            end
            if not isNull(dataInLogic) and not isNull(dataInlist) then
                if dataInLogic.roleId ~= dataInlist.roleId or dataInLogic.skillId ~= dataInlist.skillId or dataInLogic.star ~= dataInlist.star then
                    print(table.dump({ "->卡牌不同", logic = dataInLogic, ui = dataInlist}))
                    return false
                end
            end
        end
        return true
    end
    if #listTop ~= #self.skillPoolArrOriginDataTop or #listDown ~= #self.skillPoolArrOriginDataDown then
        print("->CheckSkillListSync:长度不等")
        return false
    end
    return _CheckSync(self.skillPoolArrOriginDataTop, listTop) and _CheckSync(self.skillPoolArrOriginDataDown, listDown)
end

