            table.insert(skillListTop, 
                    SkillDataVo.New(skillCardLB.Env.skillCardRoleId, 
                    UIBattlingDataMgr:GetSkillIdByCamp(BattleInfo.myCamp, skillCardLB.Env.skillCardRoleId, skillCardLB.Env.skillIndex), 
                    skillCardLB.Env.skillCardStarLevel))
        end
    end
    for i, v in ipairs(self.skillPoolTransArrLineDown) do
        local skillCardLB = v.luaBehaviour
        if not isNull(skillCardLB) then
            -- print("->UIBattlingSkillPoolPanel:GetSkillPoolDataByClient_LineD:",skillCardLB.Env.skillCardRoleId,
            --         skillCardLB.Env.skillIndex,
            --         skillCardLB.Env.skillCardStarLevel,
