---ReloadSkillCardPoolListData
---复用牌库 信息重新加载（根据补卡的逻辑数据，生成UI卡牌，存放在缓存Root下）
function UIBattlingSkillPoolPanel:ReloadSkillCardPoolListData()
    for i = 1, #self.showSequenceListTop do
        local skillCardNodeLB = GetLuaBehaviour(UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_SKILLCARD_GO, self.CardCreateRoot_1), Constants.UIBattlingLuaTablePath.SkillCardsNodePath)
        skillCardNodeLB.Env:SetSkillCardInfo(self.showSequenceListTop[i])
        skillCardNodeLB.Env:SetSkillCardsPoolGO(self.SkillCardsPool.gameObject)
        skillCardNodeLB.Env:SetSkillCardAlphaZero()
        --- New 重设技能卡游戏物体 缩放
        skillCardNodeLB.Env.defaultScale = SkillCardScale
        skillCardNodeLB.Env.controller.transform.localScale = Vector3.one * SkillCardScale
    end
    for i = 1, #self.showSequenceListDown do
        local skillCardNodeLB = GetLuaBehaviour(UIBattlingTools.ReloadPoolObjGO(Constants.UIBattlingObjPoolPrefabs.PATH_SKILLCARD_GO, self.CardCreateRoot_2), Constants.UIBattlingLuaTablePath.SkillCardsNodePath)
        skillCardNodeLB.Env:SetSkillCardInfo(self.showSequenceListDown[i])
        skillCardNodeLB.Env:SetSkillCardsPoolGO(self.SkillCardsPool.gameObject)
        skillCardNodeLB.Env:SetSkillCardAlphaZero()
        --- New 重设技能卡游戏物体 缩放
        skillCardNodeLB.Env.defaultScale = SkillCardScale
        skillCardNodeLB.Env.controller.transform.localScale = Vector3.one * SkillCardScale
    end
    -- print("->TestReset_UIBattlingSkillPoolPanel:ReloadSkillCardPoolListData:", 
    --         table.dump(checkTable(self.showSequenceListTop)),table.dump(checkTable(self.showSequenceListDown)))
end

---ShowSkillCardsPool
---卡牌入卡牌池（从缓存Root下获取UI卡牌，补到卡池正确的位置上，并播放补牌动画）
function UIBattlingSkillPoolPanel:ShowSkillCardsPool()
    xTry(function() 
    if table.count(self.showList) > 0 then
        self.showList = nil
        self.showList = {}
    end
    local LineTopIndex = self:GetLineTopStartIndex()
    local LineDownIndex = self:GetLineDownStartIndex()
    UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_renew)
    --- 取两个 list 中较长者
    local arrLength = UIBattlingTools.SelectLargeTable(self.showSequenceListTop, self.showSequenceListDown)
    ---填充 showList
    for i = 1, arrLength do
        --- 玩家技能牌池 上
        if not IsNull(self.showSequenceListTop[i]) then
            if LineTopIndex > 0 and LineTopIndex <= 5 then
                table.insert(self.showList, self.CardCreateRoot_1:GetChild(i - 1).gameObject)
                local cardNodeLB = self.CardCreateRoot_1:GetChild(i - 1).gameObject:GetComponent(typeof(LuaBehaviour))
                cardNodeLB.Env:SetCardAimTrans(self.skillPoolTransArrLineTop[LineTopIndex].position)
                cardNodeLB.Env:SetSkillCardPosInfo(1, LineTopIndex)
                self.skillPoolTransArrLineTop[LineTopIndex].luaBehaviour = cardNodeLB
                LineTopIndex = LineTopIndex + 1
            end
        end
        --- 玩家技能牌池 下
        if not IsNull(self.showSequenceListDown[i]) then
            if LineDownIndex > 0 and LineDownIndex <= 5 then
                table.insert(self.showList, self.CardCreateRoot_2:GetChild(i - 1).gameObject)
                local cardNodeLB = self.CardCreateRoot_2:GetChild(i - 1).gameObject:GetComponent(typeof(LuaBehaviour))
                cardNodeLB.Env:SetCardAimTrans(self.skillPoolTransArrLineDown[LineDownIndex].position)
                cardNodeLB.Env:SetSkillCardPosInfo(2, LineDownIndex)
                self.skillPoolTransArrLineDown[LineDownIndex].luaBehaviour = cardNodeLB
                LineDownIndex = LineDownIndex + 1
            end
        end
    end
    for i = 1, table.count(self.showList) do
        local skillCardNode = GetLuaBehaviour(self.showList[i], Constants.UIBattlingLuaTablePath.SkillCardsNodePath)
        skillCardNode.Env:ShowEffectSequence()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(Constants.TIME_OF_SHOW_NEXT_SKILLCARD))
    end
    self:ShowSPMaxFX()  -- 补出大招卡的时候才在角色身上显示特效
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.13))
    --- 添加 延时 保护
    for i = 1, 3 do
        cs_coroutine.yield_return()
    end
    end)
end

function UIBattlingSkillPoolPanel:ShowSPMaxFX()
    for i, card in ipairs(self.showSequenceListDown) do
        if card.skillIndex == 0 then
            local roleView = BattleViewMgr:FindRoleView(card.roleId)
            if roleView and roleView.isPlayer then
                roleView:PlaySPFX()
            end
        end
    end
    for i, card in ipairs(self.showSequenceListTop) do
        if card.skillIndex == 0 then
            local roleView = BattleViewMgr:FindRoleView(card.roleId)
            if roleView and roleView.isPlayer then
                roleView:PlaySPFX()
            end
        end
    end
end

------------------------------------------------SkillCardExchangePos

function UIBattlingSkillPoolPanel:SkillCardExchangePos(data)
    local curSelectSkillCardLB = nil
    local curBeChangedSkillCardLB = nil
    local curSelectSkillCardLine = nil
    local curBeChangeSkillCardLine = nil
    ---确定 玩家选择的卡牌
    if data.s[2] == 1 then
        curSelectSkillCardLine = self.skillPoolTransArrLineTop
        curSelectSkillCardLB = self.skillPoolTransArrLineTop[data.s[1]].luaBehaviour
    else
        curSelectSkillCardLine = self.skillPoolTransArrLineDown
        curSelectSkillCardLB = self.skillPoolTransArrLineDown[data.s[1]].luaBehaviour
    end
    ---确定被交换的卡牌
    if data.d[2] == 1 then
        curBeChangeSkillCardLine = self.skillPoolTransArrLineTop
        curBeChangedSkillCardLB = self.skillPoolTransArrLineTop[data.d[1]].luaBehaviour
    else
        curBeChangeSkillCardLine = self.skillPoolTransArrLineDown
        curBeChangedSkillCardLB = self.skillPoolTransArrLineDown[data.d[1]].luaBehaviour
    end
    --- 获取卡牌父节点信息
    local curSelectedCardFather = curSelectSkillCardLB.Env:GetFatherTrans()
    local curBeChangedSkillCardFather = curBeChangedSkillCardLB.Env:GetFatherTrans()
    --- 交换卡牌位置
    KTool.SetParent(curSelectSkillCardLB.gameObject, curBeChangedSkillCardFather.gameObject)
    curSelectSkillCardLB.Env:SetFatherTrans(curBeChangedSkillCardFather)
    KTool.SetParent(curBeChangedSkillCardLB.gameObject, curSelectedCardFather.gameObject)
    curBeChangedSkillCardLB.Env:SetFatherTrans(curSelectedCardFather)
    --- 更新卡牌池位置LB信息
    curSelectSkillCardLine[data.s[1]].luaBehaviour = curBeChangedSkillCardLB
    curBeChangeSkillCardLine[data.d[1]].luaBehaviour = curSelectSkillCardLB
    --- 更新卡牌位置信息
    curSelectSkillCardLB.Env:SetSkillCardPosInfo(data.d[2], data.d[1])
    curBeChangedSkillCardLB.Env:SetSkillCardPosInfo(data.s[2], data.s[1])
end
