---SkillCardUnit
---卡牌合成
---@param data table
function UIBattlingSkillPoolPanel:SkillCardUnit(data)
    local moveObjLine = data.s[2] -- 出现空位的 行
    local moveSkillCardPos = data.s[1] -- 移动消失的 技能牌
    local targetObjLine = data.d[2]
    local upgradeSkillCardPos = data.d[1] -- 升级的 技能牌
    local moveLine = self:SelectSkillCardAimLine(moveObjLine) -- 移动目标行
    local targetLine = self:SelectSkillCardAimLine(targetObjLine) -- 升级技能卡目标行
    self:SetFakerSkillCardShowState(false) -- 残影牌 消失
    self:CleanPTCSkillCardMerge()
    local unitType = (targetObjLine == moveObjLine) and 2 or 1
    cs_coroutine.yield_return(self:SkillCardUnitShow(moveLine, moveSkillCardPos, targetLine, upgradeSkillCardPos, moveObjLine, unitType))
end

---SkillCardUnitShow
---展示 技能卡 合成表现
---@param moveLine table
---@param moveSkillCardPos table
---@param targetLine table
---@param upgradeSkillCardPos table
---@param moveObjLine table
---@param unitType table
function UIBattlingSkillPoolPanel:SkillCardUnitShow(moveLine, moveSkillCardPos, targetLine, upgradeSkillCardPos, moveObjLine, unitType)
    local moveSkillCardLB = moveLine[moveSkillCardPos].luaBehaviour
    local upgradeSkillCardLB = targetLine[upgradeSkillCardPos].luaBehaviour
    if isNull(moveSkillCardLB) or isNull(upgradeSkillCardLB) then return end
    moveSkillCardLB.Env:SetEventReceiverEnableState(false)
    upgradeSkillCardLB.Env:SetEventReceiverEnableState(false)
    UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_fusion_02)
    --- 被融合卡牌 动画
    moveSkillCardLB.Env:AnimationSkillCardBeUnit(unitType)
    --- 晋升卡牌 动画
    cs_coroutine.yield_return(upgradeSkillCardLB.Env:AnimationSkillCardUpgrade(unitType))
    UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_fusion_03)
    --- 被融合卡牌逻辑位置 置空
    moveLine[moveSkillCardPos].luaBehaviour = nil
    Events.Broadcast(Constants.EventNames.UIBattlingUnitComboPanelAction,
            { eventType = Constants.UnitPanelAction.SetComboPoint, trailStart = targetLine[upgradeSkillCardPos].position })
    cs_coroutine.yield_return()
    upgradeSkillCardLB.Env:SetEventReceiverEnableState(true)
    --- 卡牌 规整
    cs_coroutine.yield_return(self:SkillCardArrange(moveObjLine, moveSkillCardPos))
    ---卡牌升级表现
    -- upgradeSkillCardLB.Env:UpgradeSkillCard()    -- 升级表现移动到合成动画过程中了
end

---SetLineShowState
---设置 卡牌合成连线
---@param boolean boolean @ 是否显示
---@param posData Vector3 @ {posStart, posEnd}
function UIBattlingSkillPoolPanel:SetLineShowState(boolean, posData)
    if boolean then
        if IsNull(self.ptcSkillCardUnitLine) then
            local goLine = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_CARD_SKILLCARD_UNITSHOW_LINE, self.SkillCardsPool.gameObject, 9999, true)
            self.ptcSkillCardUnitLine = goLine:GetComponent(typeof(LineRenderersController))
        end
        if not IsNull(posData) then
            self.ptcSkillCardUnitLine:SetPositions(posData[1], posData[2])
            --UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_fusion_01)
        end
    else
        if not IsNull(self.ptcSkillCardUnitLine) then
            UIBattlingTools.RecyclePoolObj(self.ptcSkillCardUnitLine.gameObject)
            self.ptcSkillCardUnitLine = nil
        end
    end
    if IsNull(self.ptcSkillCardUnitLine) then
        UIBattlingTools.StopAudio(UISheets.UI_Battle.ui_skill_card_fusion_01)
        -- print("--->UIBattlingTools.StopAudio(UISheets.UI_Battle.ui_skill_card_fusion_01)", self.loopAudio)
        self.loopAudio = nil
    else
        if isNull(self.loopAudio) then
            self.loopAudio = UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_fusion_01)
            -- print("--->UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_fusion_01)", self.loopAudio)
        end
    end
end
