function UIBattlingSkillPoolPanel:SkillPoolArrange()
    local _ArrangeAimLine = function(refLine)
        local tempArr = {}
        --- 填充临时 DataList
        for i = 1, #refLine do
            if not IsNull(refLine[i].luaBehaviour) then
                table.insert(tempArr, refLine[i].luaBehaviour)
            end
        end
        --- 卡牌归整
        if #tempArr > 0 then
            for i = 1, #refLine do
                if i <= #tempArr then
                    refLine[i].luaBehaviour = tempArr[i]
                    refLine[i].luaBehaviour.Env:SetSkillCardPos(i)
                    refLine[i].luaBehaviour.Env:SkillCardArrange(refLine[i].position)
                else
                    refLine[i].luaBehaviour = nil
                end
            end
        end
    end
    _ArrangeAimLine(self.skillPoolTransArrLineTop)
    _ArrangeAimLine(self.skillPoolTransArrLineDown)
end

---SkillCardDelete
---卡牌移除
---@param data table
function UIBattlingSkillPoolPanel:SkillCardDelete(data)
    -- print("->UIBattlingSkillPoolPanel:SkillCardDelete", table.dump(data), table.dump(data.pa))
    self:SetFakerSkillCardShowState(false)
    local removeType = data.rt --移除类型，0普通，1吞噬
    local removeSkillCardLineTop = {} -- 行1移出卡牌的 pos list
    local removeSkillCardLineDown = {}
    --- 填充需要消除的 技能卡所在行位置
    for i = 1, #data.pa do
        local line = data.pa[i][2] -- 行信息
        local pos = data.pa[i][1] -- 行位置信息
        table.insert(checkInt(line) == 1 and removeSkillCardLineTop or removeSkillCardLineDown, pos)
    end
    if #removeSkillCardLineTop > 0 then
        --- 清空消除点的 luaBehaviour
        for i = 1, #self.skillPoolTransArrLineTop do
            for j = 1, #removeSkillCardLineTop do
                if removeSkillCardLineTop[j] == i then
                    local lbSkillCard = self.skillPoolTransArrLineTop[i].luaBehaviour -- 对应位置上的 技能卡 LuaBehavior 对象
                    if lbSkillCard then
                        local skillCard = lbSkillCard.Env
                        if removeType and removeType == 1 then
                            SkillPoolOperationMgr:TargetCardEatCardShow(skillCard)
                            self:ClearSkillPoolLocal(skillCard.curTransArrLine, skillCard.curTransArrLinePos)
                        else
                            skillCard:SetSkillCardDefault()
                            self.skillPoolTransArrLineTop[i].luaBehaviour = nil
                        end
                        
                    end
                end
            end
        end
    end
    if #removeSkillCardLineDown > 0 then
        --- 清空消除点的 luaBehaviour
        for i = 1, #self.skillPoolTransArrLineDown do
            for j = 1, #removeSkillCardLineDown do
                if removeSkillCardLineDown[j] == i then
                    local lbSkillCard = self.skillPoolTransArrLineDown[i].luaBehaviour -- 对应位置上的 技能卡 LuaBehavior 对象
                    if lbSkillCard then
                        local skillCard = lbSkillCard.Env
                        if removeType and removeType == 1 then
                            SkillPoolOperationMgr:TargetCardEatCardShow(skillCard)
                            self:ClearSkillPoolLocal(skillCard.curTransArrLine, skillCard.curTransArrLinePos)
                        else
                            skillCard:SetSkillCardDefault()
                            self.skillPoolTransArrLineDown[i].luaBehaviour = nil
                        end
                        
                    end
                end
            end
        end
    end
    if removeType and removeType ~= 1 then
        self:SkillPoolArrange()
    end
end
