---SkillCardChange
---卡牌变换
---@param data table
function UIBattlingSkillPoolPanel:SkillCardChange(data)
    local line = data.p[2]
    local pos = data.p[1]
    local l = Tools.splitToNum(data.d, "_")
    local cardRoleId = l[1]
    local cardSkillId = l[2]
    local cardStarLv = l[3]
    local cardDataForSkillCardLB = SkillDataVo.New(cardRoleId, UIBattlingDataMgr:GetSkillIdByCamp(BattleInfo.myCamp, cardRoleId, cardSkillId), cardStarLv, cardSkillId)
    local aimLine = self:SelectSkillCardAimLine(line)
    local aimSkillCardLB = aimLine[pos].luaBehaviour
    if not IsNull(aimSkillCardLB) then
        -- 星级变化的特效
        if UIBattlingTools.IsOnlyStarChanged(aimSkillCardLB.Env.skillCardData, cardDataForSkillCardLB) then
            aimSkillCardLB.Env:PlayChangeCardStarEffect(aimSkillCardLB.Env.skillCardData.star, cardDataForSkillCardLB.star)
        end
        aimSkillCardLB.Env:SetSkillCardInfo(cardDataForSkillCardLB)
    end
end
