function UIBattlingSkillPoolPanel:CheckSkillCardLockStatus(skillCard)
    local abandonSkillCardList = self.battleUIMgr.abandonSkillCardList
    local skillRoleIndex = skillCard.skillCardRoleId
    local skillIndex = skillCard.skillIndex
    for i = 1, #abandonSkillCardList do
        local role = abandonSkillCardList[i]
        for j = 1, #role do
            if skillRoleIndex == i and skillIndex == role[j] then
                return true
            end
        end
    end
    return false
end

---AbandonSkillCard
---卡片禁用
function UIBattlingSkillPoolPanel:AbandonSkillCard()
    local abandonSkillCardList = self.battleUIMgr.abandonSkillCardList
    -- print("->UIBattlingSkillPoolPanel:AbandonSkillCard", table.dump(abandonSkillCardList))
    if IsNull(abandonSkillCardList) then return end
    for i = 1, #self.skillPoolTransArrLineTop do
        if not isNull(self.skillPoolTransArrLineTop[i].luaBehaviour) then
            self.skillPoolTransArrLineTop[i].luaBehaviour.Env:UnSkillCardLocked()
        end
    end
    for i = 1, #self.skillPoolTransArrLineDown do
        if not isNull(self.skillPoolTransArrLineDown[i].luaBehaviour) then
            self.skillPoolTransArrLineDown[i].luaBehaviour.Env:UnSkillCardLocked()
        end
    end
    if table.count(abandonSkillCardList) <= 0 then return end
    for i = 1, #self.skillPoolTransArrLineTop do
        if not isNull(self.skillPoolTransArrLineTop[i].luaBehaviour) then
            local skillCard = self.skillPoolTransArrLineTop[i].luaBehaviour.Env
            if self.battleUIMgr:CheckSkillCardLockStatus(skillCard) then
                skillCard:SkillCardLocked()
                -- print("[办卡] 禁用卡牌:", skillCard.skillCardRoleId, skillCard.skillIndex, skillCard, skillCard.isLocked)
            end
        end
    end
    for i = 1, #self.skillPoolTransArrLineDown do
        if not isNull(self.skillPoolTransArrLineDown[i].luaBehaviour) then
            local skillCard = self.skillPoolTransArrLineDown[i].luaBehaviour.Env
            if self.battleUIMgr:CheckSkillCardLockStatus(skillCard) then
                skillCard:SkillCardLocked()
                -- print("[办卡] 禁用卡牌:", skillCard.skillCardRoleId, skillCard.skillIndex, skillCard, skillCard.isLocked)
            end
        end
    end
end
