------------------------------------------------SkillCardInteractable
---OnDragOfSkillCard
---@param pos Vector3
---@param curLB XLua.LuaTable
function UIBattlingSkillPoolPanel:OnDragOfSkillCard(pos, curLB)
    local skillCardAnchoredPosX = pos.x
    if IsNull(self.curSelectSkillCardLB) or self.curSelectSkillCardLB ~= curLB then
        self.curSelectSkillCardLB = curLB
    end
    if isNull(self.listSkillCardsShowWBU) then
        self.listSkillCardsShowWBU = self:GetSkillCardsSameAsSelected(self.curSelectSkillCardLB)
        if #self.listSkillCardsShowWBU > 0 then
            for i, skillCard in pairs(self.listSkillCardsShowWBU) do
                skillCard:ShowPTCOfWillBeUnit(true)
            end
        end
    end
    local curSkillCardTranArr = pos.y > 0 and self.skillPoolTransArrLineTop or self.skillPoolTransArrLineDown
    local otherSkillCardTransArr = pos.y > 0 and self.skillPoolTransArrLineDown or self.skillPoolTransArrLineTop
    --- 求该行 x 坐标 与 CSSK 差值最小点
    --- 取唯一值 方便管理
    local curSkillCardTrans
    local disAbsFinal
    for i = 1, #curSkillCardTranArr do
        if IsNull(curSkillCardTrans) then
            curSkillCardTrans = curSkillCardTranArr[i]
            disAbsFinal = math.abs(curSkillCardTranArr[i].position.anchoredPosition.x - skillCardAnchoredPosX)
        else
            local disAbsNow = math.abs(curSkillCardTranArr[i].position.anchoredPosition.x - skillCardAnchoredPosX)
            if disAbsNow <= disAbsFinal then
                curSkillCardTrans = curSkillCardTranArr[i]
                disAbsFinal = disAbsNow
            end
        end
    end
    --- 卡牌位置替换提示与还原状态
    if not IsNull(curSkillCardTrans) then
        --- 存在 CSK
        --- or CSK ~= CSSK
        --- or 达到可展示距离
        if disAbsFinal <= Constants.EDGE_OF_EXCHANGE_SKILLCARD and not IsNull(curSkillCardTrans.luaBehaviour) and curSkillCardTrans.luaBehaviour ~= self.curSelectSkillCardLB then
            --- 存在 CSK && CSK ~= CSSK
            if not IsNull(self.curWillBeChangePosSkillCardLB) then
                --- 有当前WSK
                --- 当前 WSK 和 CWSK 是否为同一对象
                if self.curWillBeChangePosSkillCardLB ~= curSkillCardTrans.luaBehaviour then
                    --- CWSK 对象改变刷新 UnitPTC 状态
                    if not IsNull(self.curSelectSkillCardLB) then
                        --self.curSelectSkillCardLB.Env:ShowPTCOfWillBeUnit(false)
                    end
                    if not IsNull(self.curWillBeUnitSkillCardLB) then
                        --self.curWillBeUnitSkillCardLB.Env:ShowPTCOfWillBeUnit(false)
                        self.curWillBeUnitSkillCardLB = nil
                    end
                    self:SetLineShowState(false)
                    self.curWillBeChangePosSkillCardLB.Env:SkillCardDefautState()
                    self:CleanPTCSkillCardMerge()
                    
                    self.curWillBeChangePosSkillCardLB = curSkillCardTrans.luaBehaviour
                    self.curWillBeChangePosSkillCardLB.Env:OnBeOverStateOfSelectSkillCard()
                    self:SetTimerState(1)
                    local selectSkillCard = self.curSelectSkillCardLB.Env
                    local willBeChangePosSkillCard = self.curWillBeChangePosSkillCardLB.Env
                    self:SetPTCSkillCardMerge(selectSkillCard, willBeChangePosSkillCard)
                end
            else
                self.curWillBeChangePosSkillCardLB = curSkillCardTrans.luaBehaviour
                self.curWillBeChangePosSkillCardLB.Env:OnBeOverStateOfSelectSkillCard()
                self:SetTimerState(1)
                local selectSkillCard = self.curSelectSkillCardLB.Env
                local willBeChangePosSkillCard = self.curWillBeChangePosSkillCardLB.Env
                self:SetPTCSkillCardMerge(selectSkillCard, willBeChangePosSkillCard)
            end
            --- 预览合成PTC
            self.curWillBeUnitSkillCardLB = self:SkillCardWillBeUnitShow()
            if not IsNull(self.curWillBeUnitSkillCardLB) then
                --self.curWillBeUnitSkillCardLB.Env:ShowPTCOfWillBeUnit(true, pos)
                local posBeUnit = self.curWillBeUnitSkillCardLB.Env:GetFatherTrans().localPosition
                local posSelected = self.curSelectSkillCardLB.transform.localPosition
                self:SetLineShowState(true, { posBeUnit, posSelected })
                --self.curWillBeUnitSkillCardLB.Env:ShowPTCOfWillBeUnit(true)
                --.curSelectSkillCardLB.Env:ShowPTCOfWillBeUnit(true)
            end
        else
            self:SetDefaultOfShowEffectSkillCard()
        end
    end
end

function UIBattlingSkillPoolPanel:SetPTCSkillCardMerge(selectSkillCard, willBeChangePosSkillCard)
    if self:SkillCardsCanUnite(selectSkillCard, willBeChangePosSkillCard) then
        self.ptcSkillCardMerge = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_CARD_UNITSHOW_MERGE, willBeChangePosSkillCard.ParticalRoot.gameObject, 99999, true)
    end
end

function UIBattlingSkillPoolPanel:CleanPTCSkillCardMerge()
    if not IsNull(self.ptcSkillCardMerge) then
        UIBattlingTools.RecyclePoolObj(self.ptcSkillCardMerge)
        self.ptcSkillCardMerge = nil
    end
end

---SkillCardDragEnd
---技能卡 拖动完成
---@param skillCardGO UnityEngine.GameObject
function UIBattlingSkillPoolPanel:SkillCardDragEnd(skillCardGO)
    local skillCardAnchoredPosX = skillCardGO.transform.anchoredPosition.x
    local skillCardAnchoredPosY = skillCardGO.transform.anchoredPosition.y
    local curSkillCardTranArr = self:SelectSkillCardAimLine(skillCardAnchoredPosY > 0 and 1 or 2)
    local skillCardNode = GetLuaBehaviour(skillCardGO, Constants.UIBattlingLuaTablePath.SkillCardsNodePath)
    local selectedCardFather = skillCardNode.Env:GetFatherTrans()
    --self:CleanListSkillCardsShowWBU()
    for i = 1, #curSkillCardTranArr do
        if skillCardAnchoredPosX >= curSkillCardTranArr[i].position.anchoredPosition.x - Constants.EDGE_OF_EXCHANGE_SKILLCARD
                and skillCardAnchoredPosX <= curSkillCardTranArr[i].position.anchoredPosition.x + Constants.EDGE_OF_EXCHANGE_SKILLCARD
        then
            if not (curSkillCardTranArr[i].position.anchoredPosition.x == selectedCardFather.anchoredPosition.x and curSkillCardTranArr[i].position.anchoredPosition.y == selectedCardFather.anchoredPosition.y)
                    and not IsNull(curSkillCardTranArr[i].luaBehaviour) then
                ---交换的卡牌
                local lbBeExchange = curSkillCardTranArr[i].luaBehaviour
                local data = {
                    src = { skillCardNode.Env:GetSkillCardPosInfo(), skillCardNode.Env:GetSkillCardLineInfo() },
                    dst = { lbBeExchange.Env:GetSkillCardPosInfo(), lbBeExchange.Env:GetSkillCardLineInfo() }
                }
                ---向 逻辑层发送 位置交换 信息
                Events.Broadcast(Constants.EventNames.BattleInputExchange, data)
                return true
            end
        end
    end
    return false
end

------------------------------------------------SkillCardWillBeUnitShow

---SkillCardWillBeUnitShow
---技能卡合成预览展示
---@return XLua.LuaTable 展示可合成特效得技能卡对象
function UIBattlingSkillPoolPanel:SkillCardWillBeUnitShow()
    if IsNull(self.curSelectSkillCardLB) or IsNull(self.curWillBeChangePosSkillCardLB) then return
    end
    return self:CheckLocalSkillCardWillBeUnite(self.curSelectSkillCardLB, self.curWillBeChangePosSkillCardLB)
end

---CheckLocalSkillCardWillBeUnite
---检查 技能卡 的周围位置, 返回可能会合成的技能卡对象
---@param lbSkillCardLB Engine.Modules.LuaBehaviour @ 目标技能卡对象的 LuaBehaviour
---@param posSkillCardLB Engine.Modules.LuaBehaviour @ 比照位置的技能卡对象的 LuaBehaviour
function UIBattlingSkillPoolPanel:CheckLocalSkillCardWillBeUnite(lbSkillCardLB, posSkillCardLB)
    --- 需要展示的 skillCardLB
    local showLB
    --- 获取 WBCSK 的所在行
    local curWillBeChangePosSkillCardLine = posSkillCardLB.Env:GetSkillCardLineInfo()
    --- 获取 WBCSK 在所在行的位置
    local curWillBeChangePosSkillCardPos = posSkillCardLB.Env:GetSkillCardPosInfo()
    --- 所在行 list
    local transArrOfWBCSK
    --- 另一行 list
    local transArrOther
    if curWillBeChangePosSkillCardLine == 1 then
        transArrOfWBCSK = self.skillPoolTransArrLineTop
        transArrOther = self.skillPoolTransArrLineDown
    else
        transArrOfWBCSK = self.skillPoolTransArrLineDown
        transArrOther = self.skillPoolTransArrLineTop
    end
    --- 当前选择的技能卡LB
    local curLB = lbSkillCardLB
    --- 需要比较的 skillCardLB
    local aimLB
    local checkSkillCardLBID
    --- 获取 WBCSK 周围需要检测的位置 1(当前行 左)
    checkSkillCardLBID = curWillBeChangePosSkillCardPos + 1
    if checkSkillCardLBID <= 5 then
        aimLB = transArrOfWBCSK[checkSkillCardLBID].luaBehaviour
    end
    if not IsNull(aimLB) then
        if self:CompareSkillCardAboutSkillInfo(curLB, aimLB) then
            showLB = aimLB
            return showLB
        end
    end
    --- 获取 WBCSK 周围需要检测的位置 2(当前行 右)
    checkSkillCardLBID = curWillBeChangePosSkillCardPos - 1
    if checkSkillCardLBID > 0 then
        aimLB = transArrOfWBCSK[checkSkillCardLBID].luaBehaviour
    end
    if not IsNull(aimLB) then
        if self:CompareSkillCardAboutSkillInfo(curLB, aimLB) then
            showLB = aimLB
            return showLB
        end
    end
    --- 获取 WBCSK 周围需要检测的位置 3(另行同位置)
    checkSkillCardLBID = curWillBeChangePosSkillCardPos
    aimLB = transArrOther[checkSkillCardLBID].luaBehaviour
    if not IsNull(aimLB) then
        if self:CompareSkillCardAboutSkillInfo(curLB, aimLB) then
            showLB = aimLB
            return showLB
        end
    end
    return showLB
end

---CompareSkillCardAboutSkillInfo
---比较技能卡技能信息
---@param aimSkillCardLB table 目标技能卡
function UIBattlingSkillPoolPanel:CompareSkillCardAboutSkillInfo(curSkillCardLB, aimSkillCardLB)
    if IsNull(curSkillCardLB) or IsNull(aimSkillCardLB) then
        return false
    end
    local curSelectSkillCardSkillId = curSkillCardLB.Env:GetSkillCardSkillId()
    local curSelectSkillCardSkillStarLevel = curSkillCardLB.Env:GetSkillCardStarLevel()
    --self.curSelectSkillCardLB.Env:GetSkillCardStarLevel()
    local curAimSkillCardSkillId = aimSkillCardLB.Env:GetSkillCardSkillId()
    local curAimSkillCardSkillStarLevel = aimSkillCardLB.Env:GetSkillCardStarLevel()
    --- 排除三星无法合成,无法与自己比较,
    --- 技能Id相同, 技能星级相同
    if curSelectSkillCardSkillStarLevel ~= 3
            and curSkillCardLB ~= aimSkillCardLB
            and curSelectSkillCardSkillId == curAimSkillCardSkillId
            and curSelectSkillCardSkillStarLevel == curAimSkillCardSkillStarLevel
    then
        return true
    else
        return false
    end
end

