---FakerSkillCardSetInfoOfWCSK
---将残影牌设置为将要交换的技能牌信息
function UIBattlingSkillPoolPanel:FakerSkillCardSetInfoOfWCSK()
    if IsNull(self.objFakeSkillCard) then return end
    local fakerSkillCard = self.objFakeSkillCard.Env
    local selectSkillCard = self.curSelectSkillCardLB.Env
    local willBeChangePosSkillCard = self.curWillBeChangePosSkillCardLB.Env
    if selectSkillCard and willBeChangePosSkillCard then
        local isShow = not self:SkillCardsCanUnite(selectSkillCard, willBeChangePosSkillCard)
        self:SetFakerSkillCardShowState(isShow)
    end
    if not IsNull(self.curWillBeChangePosSkillCardLB) then
        fakerSkillCard:SetSkillCardInfo(self.curWillBeChangePosSkillCardLB.Env:GetSkillCardData())
    end
end

---SetFakerSkillCardShowState
---残影牌 消失
function UIBattlingSkillPoolPanel:SetFakerSkillCardShowState(boolean)
    if not IsNull(self.objFakeSkillCard) then
        self.objFakeSkillCard.Env:SetFakerSkillCardShowState(boolean)
    end
end

---SetFakeSkillCard
---设置 残影技能牌
---@param localTrans table 创建位置
---@param cardData table 卡牌状态 0：不显示， 1：显示
function UIBattlingSkillPoolPanel:SetFakeSkillCard(localTrans, cardData)
    if IsNull(self.objFakeSkillCard) then
        self:CreateFakeSkillCard() -- 创建 残影牌
    end
    if not IsNull(localTrans) then
        local fakeSkillCardRoot = localTrans:Find("SpriteRoot")
        KTool.SetParent(self.objFakeSkillCard.gameObject, fakeSkillCardRoot.gameObject)
        self:SetFakerSkillCardShowState(true)
        self.objFakeSkillCard.Env:SetFakerSkillCardOnPlayerSelect(cardData)
    else
        self:SetFakerSkillCardShowState(false)
    end
end

---CreateFakeSkillCard
---创建 残影技能牌
function UIBattlingSkillPoolPanel:CreateFakeSkillCard()
    local loader = ResourceModule.LoadBundleSync("Prefabs/UIBattling/FakerSkillCardNode.prefab", nil, true)
    if loader.IsSuccess then
        local go = loader:Instantiate()
        -- local go = GameObject.Instantiate(loader.ResultObject)
        if not KTool.IsNull(go) then
            local t = go:GetComponent(typeof(Transform))
            t.localPosition = Vector3.zero
            t.localScale = Vector3.one * SkillCardScale
            t.name = "FakeSkillCard"
        end
        local skillCardNode = GetLuaBehaviour(go, Constants.UIBattlingLuaTablePath.FakerSkillCardsNodePath)
        if not IsNull(skillCardNode.Env) then
            skillCardNode.Env:SetFakerSkillCardShowState(true)
            self.objFakeSkillCard = skillCardNode
        end
    end
    loader:Release()
end

