---SetTimerState
--- 设置 计时器状态
---@param type integer @ 1:start 2:stop (3:ReStart, 4:Pass)
function UIBattlingSkillPoolPanel:SetTimerState(type)
    if type == 1 then
        self:CleanFakerSkillCardTimer()
        self._timer = CDTimerModule.GetInstance():AddCD(0.3,
                function(count, id)
                    if count <= 0 then
                        self._timer = nil ---置空
                        self:FakerSkillCardSetInfoOfWCSK()
                    end
                end, 1, false, true, true, true)
    elseif type == 2 then
        self:CleanFakerSkillCardTimer()
        if not IsNull(self.objFakeSkillCard) then
            self.objFakeSkillCard.Env:ReSetSelectSkillCardInfo()
        end
    end
end

function UIBattlingSkillPoolPanel:CleanFakerSkillCardTimer()
    if self._timer then
        if not IsNull(self._timer) then
            CDTimerModule.GetInstance():RemoveCD(self._timer)
        end
        self._timer = nil
    end
end

---CheckSkillPoolHasSkillCardsCanUnite
---检查当前技能卡池是否有可以合成的卡牌
function UIBattlingSkillPoolPanel:CheckSkillPoolCanUnite()
    --- 检索行数据
    local rowUnite = function(row)
        for i = 1, #row - 1 do
            local card1, card2 = row[i].luaBehaviour, row[i + 1].luaBehaviour
            if IsNull(card1) or IsNull(card2) then
                goto continue
            end
            --- 处理数据
            local table1 = card1.Env
            local table2 = card2.Env
            local willBeUnite = self:SkillCardsCanUnite(table1, table2)
            if willBeUnite then
                return willBeUnite
            end
            :: continue ::
        end
    end
    --- 检索列数据
    local colUnit = function(row1, row2)
        --- 技能卡库上下长度一致
        for i = 1, #row1 - 1 do
            local card1, card2 = row1[i].luaBehaviour, row2[i].luaBehaviour
            if IsNull(card1) or IsNull(card2) then
                goto continue
            end
            --- 处理数据
            local table1 = card1.Env
            local table2 = card2.Env
            local willBeUnite = self:SkillCardsCanUnite(table1, table2)
            if willBeUnite then
                return willBeUnite
            end
            :: continue ::
        end
    end
    --- 数据检索
    while true do
        local skillCardHas = rowUnite(self.skillPoolTransArrLineTop)
                or rowUnite(self.skillPoolTransArrLineDown)
                or colUnit(self.skillPoolTransArrLineTop, self.skillPoolTransArrLineDown)
        if not skillCardHas then
            break
        end
        return skillCardHas
    end
end

---SkillCardsCanUnite
---检测两个技能卡对象是否可以合成
---@param tableCard1 UIBattlingSkillCardsNode
---@param tableCard2 UIBattlingSkillCardsNode
function UIBattlingSkillPoolPanel:SkillCardsCanUnite(tableCard1, tableCard2)
    if IsNull(tableCard1) or IsNull(tableCard2) then return false end
    local skillCard1StarLevel = tableCard1:GetSkillCardStarLevel()
    local skillCard2StarLevel = tableCard2:GetSkillCardStarLevel()
    local skillCard1SkillId = tableCard1:GetSkillCardSkillId()
    local skillCard2SkillId = tableCard2:GetSkillCardSkillId()
    return (skillCard1StarLevel ~= 3 and skillCard2StarLevel ~= 3
            and tableCard1 ~= tableCard2
            and skillCard1StarLevel == skillCard2StarLevel
            and skillCard1SkillId == skillCard2SkillId) and true or false
end


function UIBattlingSkillPoolPanel:GetPosIsOverSkillCardLocal(clickPos)
    local _condition = function(pointerPos, skillLocalPos)
        local width = skillLocalPos.rect.width
        local height = skillLocalPos.rect.height
        return pointerPos.x < skillLocalPos.anchoredPosition.x + width / 2
                and pointerPos.x > skillLocalPos.anchoredPosition.x - width / 2
                and pointerPos.y < skillLocalPos.anchoredPosition.y + height / 2
                and  pointerPos.y > skillLocalPos.anchoredPosition.y - height / 2
    end
    for i, skillLocal in ipairs(self.skillPoolTransArrLineTop) do
        local skillPos = skillLocal.position
        if _condition(clickPos, skillPos) then
            -- print("->AimValue:",skillLocal.luaBehaviour and table.dump({skillLocal.luaBehaviour.Env.curTransArrLine, skillLocal.luaBehaviour.Env.curTransArrLinePos}) or "nil")
            return skillLocal
        end
    end
    for i, skillLocal in ipairs(self.skillPoolTransArrLineDown) do
        local skillPos = skillLocal.position
        if _condition(clickPos, skillPos) then
            -- print("->AimValue:",skillLocal.luaBehaviour and table.dump({skillLocal.luaBehaviour.Env.curTransArrLine, skillLocal.luaBehaviour.Env.curTransArrLinePos}) or "nil")
            return skillLocal
        end
    end
end

--- 获取指定位置卡牌的世界坐标
---@param line integer @ 第几行
---@param pos integer @ 第几个
function UIBattlingSkillPoolPanel:GetSkillCardWorldPos(line, pos)
    local array
    if line == 1 then
        array = self.skillPoolTransArrLineTop
    elseif line == 2 then
        array = self.skillPoolTransArrLineDown
    end
    local transform = array[pos].position
    return transform.position
end

