---GetSkillCardsByRoleId
---通过角色 Id 获取 技能卡对象
---@param roleId number 角色Id
function UIBattlingSkillPoolPanel:GetSkillCardsByRoleId(roleId)
    local listSkillCards = {}
    for i = 1, #self.skillPoolTransArrLineTop do
        --- 玩家技能卡池上
        local curSkillCard = self.skillPoolTransArrLineTop[i].luaBehaviour
        if curSkillCard then
            local lbSkillCardLB = curSkillCard.Env
            local roleIdSkillCard = lbSkillCardLB:GetSkillCardRoleId()
            if roleId == roleIdSkillCard then
                table.insert(listSkillCards, lbSkillCardLB)
            end
        end
        --- 玩家技能卡池下
        curSkillCard = self.skillPoolTransArrLineDown[i].luaBehaviour
        if curSkillCard then
            local lbSkillCardLB = curSkillCard.Env
            local roleIdSkillCard = lbSkillCardLB:GetSkillCardRoleId()
            if roleId == roleIdSkillCard then
                table.insert(listSkillCards, lbSkillCardLB)
            end
        end
    end
    return listSkillCards
end

function UIBattlingSkillPoolPanel:GetSkillCardsSameAsSelected(lbSkillCard)
    local tableResult = {}
    local skillCard = lbSkillCard.Env
    local _InsertToList = function(sSkillCard, listSkillCard, listResult)
        for i, transData in ipairs(listSkillCard) do
            local skillCardLB = transData.luaBehaviour
            if isNull(skillCardLB) then
                goto continue
            end
            local skillCardIL = skillCardLB.Env
            if self:SkillCardsCanUnite(sSkillCard, skillCardIL) then
                table.insert(listResult, skillCardIL)
            end
            :: continue ::
        end
    end
    _InsertToList(skillCard, self.skillPoolTransArrLineTop, tableResult)
    _InsertToList(skillCard, self.skillPoolTransArrLineDown, tableResult)
    if #tableResult > 0 then
        table.insert(tableResult,skillCard)
    end
    return tableResult
end


function UIBattlingSkillPoolPanel:ListSkillCardsShowWBU(bool, luaBehaviour)
    if bool then
        self:SetListSkillCardsShowWBU(luaBehaviour)
    else
        self:CleanListSkillCardsShowWBU()
    end
end

function UIBattlingSkillPoolPanel:SetListSkillCardsShowWBU(luaBehaviour)
    -- print("-->UIBattlingSkillPoolPanel:SetListSkillCardsShowWBU:", self.listSkillCardsShowWBU and table.dump(self.listSkillCardsShowWBU))
    if isNull(self.listSkillCardsShowWBU) then
        self.curSelectSkillCardLB = luaBehaviour
        self.listSkillCardsShowWBU = self:GetSkillCardsSameAsSelected(self.curSelectSkillCardLB)
        if #self.listSkillCardsShowWBU > 0 then
            for i, skillCard in pairs(self.listSkillCardsShowWBU) do
                skillCard:ShowPTCOfWillBeUnit(true)
            end
        end
    end
end

function UIBattlingSkillPoolPanel:CleanListSkillCardsShowWBU()
    if self.listSkillCardsShowWBU then
        for i, skillCard in pairs(self.listSkillCardsShowWBU) do
            skillCard:ShowPTCOfWillBeUnit(false)
        end
    end
    self.listSkillCardsShowWBU = nil
end

function UIBattlingSkillPoolPanel:ClearSkillPoolLocal(line, pos)
    if IsNull(line) or IsNull(pos) then return end
    local aimLine = line == 1 and self.skillPoolTransArrLineTop or self.skillPoolTransArrLineDown
    aimLine[pos].luaBehaviour = nil
    local tempArr = {}
    for i = 1, #aimLine do
        if not IsNull(aimLine[i].luaBehaviour) then
            table.insert(tempArr, aimLine[i].luaBehaviour)
        end
    end
    if #tempArr > 0 then
        for i = 1, #aimLine do
            if i <= #tempArr then
                aimLine[i].luaBehaviour = tempArr[i]
                aimLine[i].luaBehaviour.Env:SetSkillCardPos(i)
            else
                aimLine[i].luaBehaviour = nil
            end
        end
    end
    -- print("->UIBattlingSkillPoolPanel:ClearSkillPoolLocal:", self.skillPoolTransArrLineTop,self.skillPoolTransArrLineDown)
end

